sqlTemplate:
SELECT DISTINCT a.patient_id
FROM mamba_fact_encounter_hiv_art_card a
WHERE
    /* Clinical contact during the reporting quarter */
    a.encounter_date &gt;= :startDate
    AND a.encounter_date &lt; DATE_ADD(:endDate, INTERVAL 1 DAY)

    /* HIV patient */
    AND EXISTS (
        SELECT 1
        FROM mamba_fact_encounter_hiv_art_summary s
        WHERE s.patient_id = a.patient_id
    )

    /* Already on ART before the reporting quarter */
    AND EXISTS (
        SELECT 1
        FROM mamba_fact_patients_latest_regimen r
        WHERE r.patient_id = a.patient_id
          AND r.art_start_date IS NOT NULL
          AND r.art_start_date &lt; :startDate
    )

    /* Diagnosed with TB during a qualifying clinical contact */
    AND (
        a.tuberculosis_status LIKE '%Diagnosed%'
        OR a.tuberculosis_status LIKE '%Confirmed%'
    );
